namespace Payments;

public interface IPaymentProvider
{
    Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default);
    Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default);
}

namespace Payments;

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required.", nameof(cardToken));
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        return await _provider.ChargeAsync(cardToken, amount, cancellationToken);
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(chargeId))
            throw new ArgumentException("Charge ID is required.", nameof(chargeId));

        return await _provider.RefundAsync(chargeId, cancellationToken);
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        if (string.IsNullOrWhiteSpace(eventType))
            throw new ArgumentException("Event type is required.", nameof(eventType));
        if (string.IsNullOrWhiteSpace(payload))
            throw new ArgumentException("Payload is required.", nameof(payload));

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(WebhookStatus.Processed, "Charge confirmed"),
            "charge.failed" => new WebhookResult(WebhookStatus.Processed, "Charge failed"),
            "refund.succeeded" => new WebhookResult(WebhookStatus.Processed, "Refund confirmed"),
            _ => new WebhookResult(WebhookStatus.Ignored, $"Unknown event: {eventType}"),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(WebhookStatus Status, string Message);

public enum WebhookStatus
{
    Processed,
    Ignored,
}

using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private FakePaymentProvider _provider = null!;
    private Payments.PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    // --- Constructor ---

    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new Payments.PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    // --- ChargeAsync ---

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccessResult()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 49.99m);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderFails_ReturnsFailureResult()
    {
        _provider.ShouldFail = true;

        var result = await _gateway.ChargeAsync("tok_valid", 10m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_PassesCorrectAmountToProvider()
    {
        await _gateway.ChargeAsync("tok_abc", 75.50m);

        Assert.AreEqual(75.50m, _provider.LastChargedAmount);
        Assert.AreEqual("tok_abc", _provider.LastCardToken);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task ChargeAsync_SupportsCancellation()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    // --- RefundAsync ---

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderFails_ReturnsFailureResult()
    {
        _provider.ShouldFail = true;

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_PassesCorrectChargeIdToProvider()
    {
        await _gateway.RefundAsync("ch_456");

        Assert.AreEqual("ch_456", _provider.LastRefundedChargeId);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task RefundAsync_SupportsCancellation()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync("ch_123", cts.Token));
    }

    // --- ProcessWebhook ---

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.succeeded", "Refund confirmed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("unknown.event", "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("Unknown event", result.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidEventType_ThrowsArgumentException(string? eventType)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, "{}"));
        Assert.AreEqual("eventType", ex.ParamName);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidPayload_ThrowsArgumentException(string? payload)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", payload!));
        Assert.AreEqual("payload", ex.ParamName);
    }

    // --- Fake provider ---

    private sealed class FakePaymentProvider : IPaymentProvider
    {
        public bool ShouldFail { get; set; }
        public decimal LastChargedAmount { get; private set; }
        public string? LastCardToken { get; private set; }
        public string? LastRefundedChargeId { get; private set; }

        public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            LastCardToken = cardToken;
            LastChargedAmount = amount;
            return Task.FromResult(ShouldFail
                ? new ChargeResult("", false)
                : new ChargeResult($"ch_{Guid.NewGuid():N}", true));
        }

        public Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            LastRefundedChargeId = chargeId;
            return Task.FromResult(ShouldFail
                ? new RefundResult("", false)
                : new RefundResult($"re_{Guid.NewGuid():N}", true));
        }
    }
}

